import ast, sys
src = open('/app/submission/planner.py').read()
tree = ast.parse(src)
names = set()
for node in ast.walk(tree):
    if isinstance(node, ast.Name): names.add(node.id)
    if isinstance(node, ast.Attribute): pass
# report assigned-but-unused locals per function (rough)
for fn in [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]:
    assigned = set()
    used = set()
    for node in ast.walk(fn):
        if isinstance(node, ast.Name):
            if isinstance(node.ctx, ast.Store): assigned.add(node.id)
            else: used.add(node.id)
    unused = assigned - used - {'_'}
    if unused:
        print("unused in", fn.name, sorted(unused))
print("AST scan done")
